597	// isWebsocket returns true if r looks to be an upgrade request for WebSockets.
598	// It is a fairly naive check.
599	func isWebsocket(r *http.Request) bool {
600		return httpguts.HeaderValuesContainsToken(r.Header["Connection"], "upgrade") &&
601			httpguts.HeaderValuesContainsToken(r.Header["Upgrade"], "websocket")
602	}
603	
604	// openConnection maps an open connection to
605	// an optional function for graceful close.
606	type openConnection struct {
607		conn          io.ReadWriteCloser
608		gracefulClose func() error
609	}
610	
611	type maxLatencyWriter struct {
612		dst     io.Writer
613		flush   func() error
614		latency time.Duration // non-zero; negative means to flush immediately
615	
616		mu           sync.Mutex // protects t, flushPending, and dst.Flush
617		t            *time.Timer
618		flushPending bool
619		logger       *zap.Logger
620	}
621	
622	func (m *maxLatencyWriter) Write(p []byte) (n int, err error) {
623		m.mu.Lock()
624		defer m.mu.Unlock()
625		n, err = m.dst.Write(p)
626		if c := m.logger.Check(zapcore.DebugLevel, "wrote bytes"); c != nil {
627			c.Write(zap.Int("n", n), zap.Error(err))
628		}
629		if m.latency < 0 {
630			m.logger.Debug("flushing immediately")
631			//nolint:errcheck
632			m.flush()
633			return n, err
634		}
635		if m.flushPending {
636			m.logger.Debug("delayed flush already pending")
637			return n, err
638		}
639		if m.t == nil {
640			m.t = time.AfterFunc(m.latency, m.delayedFlush)
641		} else {
642			m.t.Reset(m.latency)
643		}
644		if c := m.logger.Check(zapcore.DebugLevel, "timer set for delayed flush"); c != nil {
645			c.Write(zap.Duration("duration", m.latency))
646		}
647		m.flushPending = true
648		return n, err
649	}
650	
651	func (m *maxLatencyWriter) delayedFlush() {
652		m.mu.Lock()
653		defer m.mu.Unlock()
654		if !m.flushPending { // if stop was called but AfterFunc already started this goroutine
655			m.logger.Debug("delayed flush is not pending")
656			return
657		}
658		m.logger.Debug("delayed flush")
659		//nolint:errcheck
660		m.flush()
661		m.flushPending = false
662	}
663	
664	func (m *maxLatencyWriter) stop() {
665		m.mu.Lock()
666		defer m.mu.Unlock()
667		m.flushPending = false
668		if m.t != nil {
669			m.t.Stop()
670		}
671	}
672	
673	// switchProtocolCopier exists so goroutines proxying data back and
674	// forth have nice names in stacks.
675	type switchProtocolCopier struct {
676		user, backend io.ReadWriteCloser
677		wg            *sync.WaitGroup
678		bufferSize    int
679	}
680	
681	// errCopyDone is reported by a direction that ended at a clean EOF on a
682	// connection whose write half cannot be closed, so the end of that direction
683	// could not be propagated to the peer.
684	var errCopyDone = errors.New("hijacked connection copy complete")
685	
686	func (c switchProtocolCopier) copyFromBackend(errc chan<- error) {
687		defer c.wg.Done()
688		if _, err := io.CopyBuffer(c.user, c.backend, c.buffer()); err != nil {
689			errc <- err
690			return
691		}
692	
693		// backend conn has reached EOF so propagate close write to user conn
694		if wc, ok := c.user.(interface{ CloseWrite() error }); ok {
695			errc <- wc.CloseWrite()
696			return
697		}
698	
699		errc <- errCopyDone
700	}
701	
702	func (c switchProtocolCopier) copyToBackend(errc chan<- error) {
703		defer c.wg.Done()
704		if _, err := io.CopyBuffer(c.backend, c.user, c.buffer()); err != nil {
705			errc <- err
706			return
707		}
708	
709		// user conn has reached EOF so propagate close write to backend conn
710		if wc, ok := c.backend.(interface{ CloseWrite() error }); ok {
711			errc <- wc.CloseWrite()
712			return
713		}
714	
715		errc <- errCopyDone
716	}
717	
718	func (c switchProtocolCopier) buffer() []byte {
719		size := c.bufferSize
720		if size <= 0 {
721			size = defaultBufferSize
722		}
723		return make([]byte, size)
724	}
725	
726	var streamingBufPool = sync.Pool{
727		New: func() any {
728			// The Pool's New function should generally only return pointer
729			// types, since a pointer can be put into the return interface
730			// value without an allocation
731			// - (from the package docs)
732			b := make([]byte, defaultBufferSize)
733			return &b
734		},
735	}
736	
737	const (
738		defaultBufferSize = 32 * 1024
739		wordSize          = int(unsafe.Sizeof(uintptr(0)))
740	)
741

