// TestExtendedConnectH2 checks that a WebSocket over HTTP/2 (extended
// CONNECT, RFC 8441) is proxied to a backend that speaks HTTP/1.1 upgrades,
// by default and with detached streams.
func TestExtendedConnectH2(t *testing.T) {
	backend := startUpgradeBackend(t)
	port := backend[strings.LastIndex(backend, ":")+1:]
	tester := caddytest.NewTester(t)

	for name, proxyOptions := range map[string]string{"default": "", "detached": "stream_detached"} {
		t.Run(name, func(t *testing.T) {
			tester.InitServer(`{
				skip_install_trust
				admin localhost:2999
				http_port     9080
				https_port    9443
				grace_period  1ns
				servers :9443 {
					protocols h1 h2
				}
			}
			localhost {
				reverse_proxy 127.0.0.1:`+port+` {
					`+proxyOptions+`
				}
			}
			`, "caddyfile")

			tr := &http2.Transport{
				DialTLSContext: func(ctx context.Context, network, addr string, cfg *tls.Config) (net.Conn, error) {
					d := tls.Dialer{Config: &tls.Config{
						InsecureSkipVerify: true, //nolint:gosec
						NextProtos:         []string{"h2"},
						ServerName:         "localhost",
					}}
					return d.DialContext(ctx, "tcp", "127.0.0.1:9443")
				},
			}
			defer tr.CloseIdleConnections()

			pr, pw := io.Pipe()
			req, err := http.NewRequest(http.MethodConnect, "https://localhost:9443/ws", pr)
			if err != nil {
				t.Fatalf("failed to create request: %v", err)
			}
			req.Header.Set(":protocol", "websocket")
			req.Header.Set("Sec-WebSocket-Version", "13")

			ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
			defer cancel()
			resp, err := tr.RoundTrip(req.WithContext(ctx))
			if err != nil {
				dbgFatalf(t, "extended CONNECT failed: %v", err)
			}
			defer resp.Body.Close()
			if resp.StatusCode != http.StatusOK {
				dbgFatalf(t, "status = %d, want 200", resp.StatusCode)
			}
			if resp.ProtoMajor != 2 {
				dbgFatalf(t, "response is HTTP/%d, want HTTP/2", resp.ProtoMajor)
			}

			for _, msg := range []string{"hello over h2", "and again"} {
				if _, err := io.WriteString(pw, msg); err != nil {
					dbgFatalf(t, "writing %q: %v", msg, err)
				}
				buf := make([]byte, len(msg))
				if _, err := io.ReadFull(resp.Body, buf); err != nil || string(buf) != msg {
					dbgFatalf(t, "echo = %q, %v; want %q", buf, err, msg)
				}
			}

			// the client ends the stream, and the server follows
			pw.Close()
			done := make(chan error, 1)
			go func() {
				_, err := io.Copy(io.Discard, resp.Body)
				done <- err
			}()
			select {
			case <-done:
			case <-time.After(15 * time.Second):
				t.Fatal("the stream was not closed after the client ended it")
			}
		})
	}
}

