// dialUpgrade sends an upgrade request for path to the HTTP port of the
// test server, and returns the client once the response headers are read.
func dialUpgrade(t *testing.T, path string, header map[string]string) *upgradeClient {
	t.Helper()
	dbgNote(t)
	conn, err := net.DialTimeout("tcp", "127.0.0.1:9080", 5*time.Second)
	if err != nil {
		dbgFatalf(t, "failed to dial the server: %v", err)
	}
	t.Cleanup(func() { conn.Close() })

	req, err := http.NewRequest(http.MethodGet, "http://localhost:9080"+path, nil)
	if err != nil {
		t.Fatalf("failed to create request: %v", err)
	}
	req.Header.Set("Connection", "Upgrade")
	req.Header.Set("Upgrade", "websocket")
	for k, v := range header {
		req.Header.Set(k, v)
	}

	conn.SetDeadline(time.Now().Add(10 * time.Second))
	if err := req.Write(conn); err != nil {
		dbgFatalf(t, "failed to write upgrade request: %v", err)
	}
	br := bufio.NewReader(conn)
	resp, err := http.ReadResponse(br, req)
	if err != nil {
		dbgFatalf(t, "failed to read upgrade response: %v", err)
	}
	if resp.StatusCode != http.StatusSwitchingProtocols {
		dbgFatalf(t, "upgrade status = %d, want %d", resp.StatusCode, http.StatusSwitchingProtocols)
	}
	return &upgradeClient{conn: conn, br: br, resp: resp}
}

var dbgFailures []string

func dbgNote(t *testing.T) {
	t.Cleanup(func() {
		dbgFailures = append(dbgFailures, fmt.Sprintf("NOTE %s failed=%v skipped=%v", t.Name(), t.Failed(), t.Skipped()))
	})
}

func dbgFatalf(t *testing.T, format string, args ...any) {
	t.Helper()
	dbgFailures = append(dbgFailures, t.Name()+": "+fmt.Sprintf(format, args...))
	t.Fatalf(format, args...)
}

// echo sends msg on the stream and expects to read it back.
func (c *upgradeClient) echo(t *testing.T, msg string) {
	t.Helper()
	c.conn.SetDeadline(time.Now().Add(10 * time.Second))
	if _, err := io.WriteString(c.conn, msg); err != nil {
		dbgFatalf(t, "writing %d bytes to the stream: %v", len(msg), err)
	}
	buf := make([]byte, len(msg))
	if _, err := io.ReadFull(c.br, buf); err != nil {
		dbgFatalf(t, "reading the echo of %d bytes: %v", len(msg), err)
	}
	if string(buf) != msg {
		dbgFatalf(t, "echo does not match what was sent (%d bytes)", len(msg))
	}
}

// expectClosed waits for the server to close the stream.
func (c *upgradeClient) expectClosed(t *testing.T, within time.Duration) {
	t.Helper()
	c.conn.SetReadDeadline(time.Now().Add(within))
	// the server may send a close message before it closes the connection
	_, err := io.Copy(io.Discard, c.br)
	var netErr net.Error
	if errors.As(err, &netErr) && netErr.Timeout() {
		dbgFatalf(t, "the stream is still open after %s", within)
	}
}

